/* Hand-encoded format controls. No writer/loader includes or generated bytes.
 * Each test changes one property and asserts the checker's specific diagnosis. */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
static uint8_t b[262224];
static void w(unsigned o,uint32_t v,unsigned n){while(n--){b[o++]=(uint8_t)v;v>>=8;}}
int main(int argc,char **argv)
{
    if(argc!=3)return 2;
    const char *kind=argv[1];unsigned size=72;
    memset(b,0,sizeof b);b[0]='M';b[1]='Z';
    w(2,size,2);w(4,1,2);w(6,1,2);w(8,4,2);w(12,65535,2);
    w(24,56,2);w(28,0x5849,2);
    w(32,1,4);w(36,24,4);w(40,32,4);w(48,65536,4);w(52,4096,4);
    w(56,4,4);b[64]=0x90;b[65]=0xc3;w(68,8,4); /* valid BSS pointer */
    if(!strcmp(kind,"version"))w(32,2,4);
    else if(!strcmp(kind,"length"))w(36,23,4);
    else if(!strcmp(kind,"stack"))w(48,65532,4);
    else if(!strcmp(kind,"guard"))w(52,0,4);
    else if(!strcmp(kind,"descriptor"))w(8,3,2);
    else if(!strcmp(kind,"table-low"))w(24,52,2);
    else if(!strcmp(kind,"table-high"))w(6,3,2);
    else if(!strcmp(kind,"site"))w(56,5,4);
    else if(!strcmp(kind,"pointer"))w(68,41,4);
    else if(!strcmp(kind,"duplicate")){w(6,2,2);w(60,4,4);}
    else if(!strcmp(kind,"entry"))w(20,8,2);
    else if(!strcmp(kind,"reserve"))w(40,0xffffffff,4);
    else if(!strcmp(kind,"header-room"))w(40,0x1ef000-8,4);
    else if(!strcmp(kind,"heap"))w(44,0xffffffff,4);
    else if(!strcmp(kind,"heap-round")){w(12,2,2);w(44,17,4);}
    else if(!strcmp(kind,"minalloc")){w(12,1,2);w(10,2,2);}
    else if(!strcmp(kind,"pages"))w(2,512,2);
    else if(!strcmp(kind,"truncated"))size--;
    else if(!strcmp(kind,"maximum")||!strcmp(kind,"maximum-good")){
        size=64+262144+(!strcmp(kind,"maximum"));
        w(2,size%512,2);w(4,(size+511)/512,2);
    }else if(strcmp(kind,"good"))return 2;
    FILE *f=fopen(argv[2],"wb");if(!f)return 2;
    if(fwrite(b,1,size,f)!=size||fclose(f))return 2;
    return 0;
}
